package io.lumine.mythic.lib.player.particle.type;
import io.lumine.mythic.lib.player.particle.*;import io.lumine.mythic.lib.util.configobject.ConfigObject;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.Vec3d;import java.util.Map;
public class FirefliesParticleEffect extends ParticleEffect{private final double speed,height,radius,rSpeed;private final int amount;private double a;public FirefliesParticleEffect(String k,Map<String,Double>m,ParticleInformation p){super(k,p);speed=resolveModifier(m,"speed");height=resolveModifier(m,"height");radius=resolveModifier(m,"radius");rSpeed=resolveModifier(m,"rotation-speed");amount=(int)resolveModifier(m,"amount");}public FirefliesParticleEffect(ConfigObject o){super(o);speed=o.getDouble("speed");height=o.getDouble("height");radius=o.getDouble("radius");rSpeed=o.getDouble("rotation-speed");amount=o.getInt("amount");}public ParticleEffectType getType(){return ParticleEffectType.FIREFLIES;}public void tick(){ServerPlayerEntity pl=playerData.getPlayer();Vec3d b=pl.getPos();int n=Math.max(1,amount);for(int k=0;k<n;k++){double x=a+Math.PI*2*k/n;particle.display(pl.getServerWorld(),b.add(Math.cos(x)*radius,height,Math.sin(x)*radius),speed);}a+=Math.PI/48*rSpeed;if(a>Math.PI*2)a-=Math.PI*2;}}
